<section class="page-section"><div class="container narrow"><div class="section-title"><h1><?= e(__($title)) ?></h1><a class="btn btn-ghost" href="<?= e(url($adminMode?'/admin':'/host')) ?>"><?= e(__('Quay lại quản lý')) ?></a></div>
<?php if(!$reviews): ?><div class="empty-state"><h2><?= e(__('Chưa có đánh giá')) ?></h2><p><?= e(__('Đánh giá sau lưu trú sẽ xuất hiện tại đây.')) ?></p></div><?php endif; ?>
<?php foreach($reviews as $review): ?><article class="surface-card mb-3"><h2 class="h5"><?= e($review['title']) ?></h2><p><?= e($review['guest_name']) ?> · <?= (int)$review['rating'] ?>/5 · <?= e($review['moderation_status']) ?></p><p><?= e($review['comment']) ?></p>
<?php if($adminMode): ?>
<?php if($review['host_reply']): ?><blockquote><?= e($review['host_reply']) ?></blockquote><?php endif; ?>
<form method="post" action="<?= e(url('/admin/reviews/'.$review['id'].'/moderate')) ?>"><?= csrf_field() ?><input type="hidden" name="status" value="<?= $review['moderation_status']==='visible'?'hidden':'visible' ?>"><button class="btn btn-outline-danger" data-confirm="<?= e(__('Cập nhật hiển thị đánh giá này? Nội dung và lịch sử vẫn được giữ.')) ?>"><?= e($review['moderation_status']==='visible'?__('Gỡ khỏi công khai'):__('Hiển thị lại')) ?></button></form>
<?php else: ?><form method="post" action="<?= e(url('/host/reviews/'.$review['id'].'/reply')) ?>"><?= csrf_field() ?><label for="reply-<?= (int)$review['id'] ?>"><?= e(__('Phản hồi của bạn')) ?></label><textarea class="form-control mb-2" id="reply-<?= (int)$review['id'] ?>" name="reply" maxlength="5000" required><?= e($review['host_reply']) ?></textarea><button class="btn btn-primary"><?= e(__('Lưu phản hồi')) ?></button></form><?php endif; ?>
</article><?php endforeach; ?></div></section>
